/* مكتبة تصدير PDF مبسطة */
function exportPDF() {
  const { jsPDF } = window.jspdf;
  const doc = new jsPDF();
  
  // إضافة خط عربي (يجب إضافة خط عربي يدعم RTL)
  doc.setFont('helvetica');
  
  // العنوان
  doc.setFontSize(24);
  doc.text(DATA.poem?.title || 'البُردة', 105, 20, { align: 'center' });
  
  // المؤلف
  doc.setFontSize(14);
  doc.text(DATA.poem?.author || '', 105, 30, { align: 'center' });
  
  // الأبيات
  let y = 45;
  doc.setFontSize(12);
  
  (DATA.verses || []).forEach(v => {
    if (y > 270) {
      doc.addPage();
      y = 20;
    }
    const text = `${v.first} ${v.second}`;
    doc.text(text, 105, y, { align: 'center' });
    y += 8;
  });
  
  doc.save('burdah.pdf');
}
